# -*- coding: utf-8 -*-
"""Phase 12: 벡터공간 (weeks 144–156)."""
from curriculum.common import phase
from curriculum.ma.resources import R12

PHASE = phase("벡터공간", 144, 156, "적분", "기저", "기저, 차원, 계수-퇴화차수, 고유값, 정사영을 증명하거나 계산한다.", R12, [
("R^n", "덧셈", "스칼라", "R^n은 성분의 덧셈과 실수 배가 있는 공간이다. 영벡터는 모든 성분이 0이다.", "(1,2)+(3,4)=(4,6). 2(1,2)=(2,4). 영벡터와 더하면 자기 자신이다.", "성분 개수가 다른 벡터를 더하면 같은 공간이 아니다.", "R^2와 R^3에서 덧셈과 스칼라 배 10문제를 푼다.", "연산이 성분마다 일어나므로 차원이 같아야 더할 수 있다.", "(1,2)+(3,4)와 그 합에 -1을 곱한 벡터를 구하고 합이 0이 되는 짝을 말한다."),
("부분공간", "닫힘", "영", "덧셈과 스칼라 배에 닫혀 있고 영을 포함하면 부분공간이다.", "R^2에서 x축은 부분공간이다. (a,0)+(b,0)은 다시 x축 위다.", "제1사분면은 음수 배를 하면 나가므로 부분공간이 아니다.", "부분집합 6개에 부분공간인지 표시하고 깨지는 연산을 적는다.", "부분공간은 자기 안에서 선형 계산이 끝나야 한다.", "제1사분면이 부분공간이 아닌 이유를 스칼라 배 하나로 보인다."),
("생성", "일차결합", "계수", "벡터들의 생성은 그 벡터들의 일차결합 전부다.", "(1,0)과 (0,1)의 생성은 R^2 전체다. 2(1,0)+3(0,1)=(2,3).", "하나의 벡터 (1,1)만으로는 (1,0)을 만들지 못한다.", "생성 문제 6개에서 목표 벡터가 일차결합인지 방정식을 풀어 판단한다.", "일차결합은 각 벡터에 실수를 곱해 더한 것이다.", "(1,0)과 (0,1)로 (2,3)을 만드는 계수를 구하고, (1,1)만으로 (1,0)이 안 되는 이유를 말한다."),
("일차독립과 소거법", "소거법", "영", "일차결합이 영벡터가 되는 방법이 모든 계수가 0인 것뿐이면 일차독립이다. 실전 판정은 행 기본연산(가우스 소거법)으로 계단행렬을 만들어 자유변수가 없는지 본다.", "(1,0)과 (0,1)은 독립이고, (1,2)와 (2,4)는 둘째 행에서 2·첫째 행을 빼면 영행이 생겨 종속이다.", "소거 없이 계수 일부만 맞추어 보거나 행 연산에서 한쪽 항만 빼면 0 아닌 해를 놓친다.", "가우스 소거법(행 교환·스칼라 배·행 더하기)으로 일차독립 판정 4개와 비동차 연립방정식 2개를 푼다.", "행 기본연산은 해집합을 바꾸지 않으면서 피벗과 자유변수를 분리해 독립성과 해의 유일성을 동시에 드러낸다.", "(1,0)과 (2,0)이 종속임을 가우스 소거법으로 보이고 2(1,0)-(2,0)=0 계수를 말한다."),
("기저와 차원", "개수", "유일", "기저는 독립이면서 전체를 생성하는 집합이다. 기저의 원소 수가 차원이다.", "R^2의 표준기저는 두 개라 차원은 2다. (1,1), (1,-1)도 기저다.", "생성하지만 독립이 아닌 집합의 원소 수를 차원이라고 하면 개수가 일정하지 않다.", "R^2와 R^3의 기저를 각 하나 만들고 차원과 개수가 같은지 확인한다.", "차원은 좌표를 유일하게 주기 위한 독립 생성 집합의 크기다.", "R^2의 기저 하나를 표준기저가 아닌 것으로 보이고 차원이 2인 이유를 말한다."),
("선형변환", "덧셈 보존", "배 보존", "선형변환은 합과 스칼라 배를 보존한다. 원점을 원점으로 보낸다.", "T(x,y)=(2x, y)는 선형이다. T(x,y)=(2x+1, y)는 T(0)이 0이 아니라 선형이 아니다.", "상수만 더해도 영벡터가 영으로 가지 않는다.", "변환 6개의 선형성을 합과 배로 확인한다.", "행렬을 곱하는 변환은 선형이다. 성분을 제곱하는 변환은 아니다.", "T(x,y)=(2x+1,y)가 선형이 아닌 이유를 영벡터로 보인다."),
("계수-퇴화차수", "핵", "차원", "선형변환의 핵의 차원과 치역의 차원을 더하면 정의역의 차원이다.", "T(x,y)=(x,0)의 핵은 y축이라 차원 1, 치역은 x축이라 차원 1, 합은 2다.", "치역의 차원을 정의역과 항상 같다고 하면 정보가 사라지는 변환을 설명하지 못한다.", "R^2에서 R^2로 가는 변환 4개의 핵과 치역 차원을 구해 합을 확인한다.", "핵은 0으로 눌리는 자유도이고, 치역은 살아남은 자유도다.", "T(x,y)=(x,0)에 대해 계수-퇴화차수 등식을 숫자로 말한다."),
("행렬 표현과 행렬식", "열", "가역", "선형변환의 행렬 열은 표준기저를 보낸 결과다. 정방행렬이 가역인지 여부는 행렬식으로 판정하며 2×2 행렬 [[a,b],[c,d]]의 행렬식은 ad-bc다.", "T(x,y)=(2x, 3y)의 행렬은 대각에 2와 3이고 행렬식은 6≠0이라 가역이다. 반면 T(x,y)=(x,x)는 행렬식이 0이라 역행렬이 없다.", "행과 열을 바꾸거나, 행렬식 ad-bc=0인데 역행렬이 있다고 계산하면 0으로 나누게 된다.", "변환 3개의 행렬을 표준기저 상으로 구하고, 2×2 행렬 4개의 행렬식 ad-bc와 가역성·역행렬을 계산한다.", "모든 벡터는 기저의 결합이므로 기저의 상이 행렬을 정하고, 행렬식은 평행사변형 넓이 배율이라 0이면 차원이 찌그러져 역이 없다.", "T(x,y)=(2x,3y)의 행렬과 행렬식을 구하고, ad-bc=0인 행렬이 왜 비가역인지 말한다."),
("기저 변환", "좌표", "바꾸기", "다른 기저에서의 좌표는 기저 변환 행렬을 곱해 얻는다. 변환의 행렬도 그 기저에 맞춰 바뀐다.", "기저 (1,1), (1,-1)에서 (2,0)의 좌표는 각 기저 벡터의 계수 1과 1이다. 1(1,1)+1(1,-1)=(2,0).", "좌표를 표준 성분과 같다고 두면 기저가 기울어진 경우 점이 다르다.", "벡터 3개의 비표준 좌표를 연립으로 구한다.", "좌표는 벡터 자체가 아니라 그 기저에 대한 계수다.", "(2,0)을 기저 (1,1), (1,-1)의 좌표로 구하고 다시 합성해 확인한다."),
("고유값", "고유벡터", "특성식", "영이 아닌 v에 대해 T(v)=λv면 λ는 고유값, v는 고유벡터다. (A-λI)v=0이 자명하지 않은 해를 가져야 한다.", "행렬 diag(2,3)의 고유값은 2와 3, 고유벡터는 (1,0)과 (0,1)이다.", "영벡터를 고유벡터라고 하면 모든 λ가 고유값이 되어 정의가 비게 된다.", "2×2 행렬 4개의 고유값과 고유벡터를 특성방정식으로 구한다.", "고유벡터는 변환이 방향을 바꾸지 않고 길이만 배율하는 방향이다.", "diag(2,3)의 고유값 둘과 각 고유벡터를 구하고 영벡터를 왜 빼는지 말한다."),
("대각화와 대칭행렬", "기저", "직교", "고유벡터로 기저를 만들 수 있으면 그 기저에서 행렬은 대각선에 고유값이 놓인다. 특히 실수 대칭행렬은 고유값이 모두 실수이고 서로 다른 고유값의 고유벡터가 수직이라 항상 직교대각화가 가능하다.", "대칭행렬 [[2,1],[1,2]]의 고유값은 3, 1이고 고유벡터 (1,1), (1,-1)이 수직이라 정규직교 기저로 대각화된다. 반면 90도 회전은 실수 고유값이 없다.", "고유값만 있고 독립 고유벡터가 모자라거나 비대칭이면 직교대각화가 안 된다. 회전 90도는 실수 고유값이 없다.", "대각화 판정 2개와 2×2 실수 대칭행렬 1개의 직교대각화 Q^T A Q = D를 직접 계산한다.", "대각행렬은 좌표를 독립 배율로 분리하며, 실수 대칭행렬의 직교대각화는 5년차 스펙트럼 정리와 SVD의 유한차원 핵심 계산이다.", "90도 회전이 실수 고유값을 갖지 않는 이유와, 대칭행렬 [[2,1],[1,2]]의 고유벡터가 수직임을 내적으로 확인한다."),
("정사영과 최소제곱", "수선", "잔차", "부분공간으로의 정사영은 잔차가 그 공간의 모든 벡터와 수직인 점이다. 최소제곱은 열공간으로의 정사영이다.", "R^2에서 (1,1)을 x축에 정사영하면 (1,0)이다. 잔차 (0,1)은 x축과 수직이다.", "가장 가까운 점이 아닌 임의의 점을 사영이라고 하면 잔차가 수직이 아니다.", "점 3개의 직선 위 정사영과, 점 3개를 지나는 직선 맞추기의 정규방정식을 하나 세운다.", "수직일 때 거리가 최소인 것은 빗변이 직각변보다 길다는 피타고라스다.", "(1,1)의 x축 정사영과 잔차가 수직인 이유를 성분으로 말한다."),
("선형대수 점검", "차원", "검산", "부분공간, 기저, 핵, 고유값을 한 행렬에 대해 계산한다.", "A=diag(2,0)의 핵은 둘째 축, 고유값은 2와 0, 계수는 1, 퇴화차수는 1이다.", "계수와 퇴화차수의 합이 2가 아니면 계산을 다시 한다.", "행렬 하나를 정해 핵, 치역 차원, 고유값을 구하고 등식을 확인한다.", "고유값 0은 그 방향으로 정보가 사라진다는 뜻이라 핵과 만난다.", "diag(2,0)의 고유값과 계수-퇴화차수를 한 세트로 말한다."),
], mode="proof")
